SET ROLE hub2_mem_owner;
CREATE TABLE mem.materials(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL,owner_id uuid NOT NULL,current_version_id uuid,content_revision bigint NOT NULL DEFAULT 0,metadata_revision bigint NOT NULL DEFAULT 0,event_revision bigint NOT NULL DEFAULT 0,state text NOT NULL DEFAULT 'active' CHECK(state IN ('active','trashed')),properties jsonb NOT NULL DEFAULT '{}',provenance_state text NOT NULL DEFAULT 'raw' CHECK(provenance_state IN ('raw','pending','declared')),origin_kind text NOT NULL,producer text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE mem.verified_objects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),provider text NOT NULL CHECK(provider<>'test-memory'),bucket text NOT NULL,object_key text NOT NULL,provider_version_id text NOT NULL CHECK(length(provider_version_id)>0 AND provider_version_id NOT IN ('null','undefined')),sha256 text NOT NULL CHECK(sha256 ~ '^[a-f0-9]{64}$'),size bigint NOT NULL CHECK(size>=0),verification_run uuid NOT NULL,availability text NOT NULL DEFAULT 'available' CHECK(availability IN ('available','suspect','unavailable')),UNIQUE(provider,bucket,object_key,provider_version_id),UNIQUE(id,sha256,size));
CREATE TABLE mem.content_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),material_id uuid NOT NULL REFERENCES mem.materials(id),version_no bigint GENERATED ALWAYS AS IDENTITY,provenance_state text NOT NULL DEFAULT 'raw' CHECK(provenance_state IN ('raw','pending','declared')),object_id uuid NOT NULL,sha256 text NOT NULL,size bigint NOT NULL,actor_id uuid NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(material_id,id),UNIQUE(material_id,id,object_id,sha256,size),FOREIGN KEY(object_id,sha256,size) REFERENCES mem.verified_objects(id,sha256,size));
ALTER TABLE mem.materials ADD FOREIGN KEY(id,current_version_id) REFERENCES mem.content_versions(material_id,id) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE mem.collections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL,name text NOT NULL,revision bigint NOT NULL DEFAULT 1);
CREATE TABLE mem.placements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),material_id uuid NOT NULL REFERENCES mem.materials(id),project_id uuid NOT NULL,collection_id uuid REFERENCES mem.collections(id),logical_path text NOT NULL,revision bigint NOT NULL DEFAULT 1,active boolean NOT NULL DEFAULT true);
CREATE UNIQUE INDEX placements_active_path ON mem.placements(project_id,logical_path) WHERE active;
CREATE TABLE mem.operations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid NOT NULL,client_id uuid NOT NULL,project_id uuid NOT NULL,material_id uuid NOT NULL REFERENCES mem.materials(id),idempotency_key text NOT NULL,fingerprint text NOT NULL,expected_version_id uuid,expected_revision bigint NOT NULL,origin_kind text NOT NULL,expected_hash text NOT NULL CHECK(expected_hash ~ '^[a-f0-9]{64}$'),expected_size bigint NOT NULL CHECK(expected_size>=0),staging_key text NOT NULL,state text NOT NULL DEFAULT 'prepared' CHECK(state IN ('prepared','uploading','verifying','verified','published','conflict','rejected','cancelled','expired')),attempt bigint NOT NULL DEFAULT 0,fencing_token uuid,lease_until timestamptz,writer_generation bigint NOT NULL DEFAULT 1,object_id uuid,result_version_id uuid,receipt jsonb,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(actor_id,idempotency_key),FOREIGN KEY(material_id,expected_version_id) REFERENCES mem.content_versions(material_id,id),FOREIGN KEY(object_id,expected_hash,expected_size) REFERENCES mem.verified_objects(id,sha256,size),FOREIGN KEY(material_id,result_version_id,object_id,expected_hash,expected_size) REFERENCES mem.content_versions(material_id,id,object_id,sha256,size),CHECK(state<>'published' OR (receipt IS NOT NULL AND result_version_id IS NOT NULL)));
CREATE TABLE mem.snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid NOT NULL,client_id uuid NOT NULL,project_id uuid NOT NULL,qualification_epoch bigint NOT NULL,items jsonb NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE mem.read_receipts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid NOT NULL,client_id uuid NOT NULL,material_id uuid NOT NULL,version_id uuid NOT NULL,sha256 text NOT NULL,range_start bigint NOT NULL,range_end bigint NOT NULL,complete boolean NOT NULL,state text NOT NULL CHECK(state IN ('prepared','sent','acknowledged')),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(material_id,version_id) REFERENCES mem.content_versions(material_id,id));
CREATE TABLE mem.processing_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL,actor_id uuid NOT NULL,client_id uuid NOT NULL,idempotency_key text NOT NULL,fingerprint text NOT NULL,reuse_fingerprint text NOT NULL,output_kind text NOT NULL,recipe jsonb NOT NULL CHECK(jsonb_typeof(recipe)='object'),inputs jsonb NOT NULL CHECK(jsonb_typeof(inputs)='array' AND jsonb_array_length(inputs)>0),outputs jsonb NOT NULL DEFAULT '[]',coverage text NOT NULL,technical_state text NOT NULL DEFAULT 'prepared',attempt bigint NOT NULL DEFAULT 1,fencing_token uuid NOT NULL DEFAULT gen_random_uuid(),lease_until timestamptz NOT NULL DEFAULT now()+interval '10 minutes',UNIQUE(actor_id,idempotency_key));
CREATE TABLE mem.source_edges(output_version_id uuid NOT NULL REFERENCES mem.content_versions(id),input_version_id uuid NOT NULL REFERENCES mem.content_versions(id),run_id uuid REFERENCES mem.processing_runs(id),derivation_kind text NOT NULL,PRIMARY KEY(output_version_id,input_version_id),CHECK(output_version_id<>input_version_id));
CREATE TABLE mem.disclosures(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),output_version_id uuid NOT NULL REFERENCES mem.content_versions(id),output_hash text NOT NULL,actual_source_closure jsonb NOT NULL,audience_project_id uuid NOT NULL,actor_id uuid NOT NULL,manifest jsonb NOT NULL,state text NOT NULL DEFAULT 'active' CHECK(state IN ('active','revoked')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE mem.invalidations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_version_id uuid NOT NULL REFERENCES mem.content_versions(id),reason text NOT NULL,actor_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE mem.stale_versions(version_id uuid PRIMARY KEY REFERENCES mem.content_versions(id),invalidation_id uuid NOT NULL REFERENCES mem.invalidations(id));
CREATE TABLE mem.text_index(version_id uuid PRIMARY KEY REFERENCES mem.content_versions(id),recipe text NOT NULL DEFAULT 'zh-character-bigram-v1',text_content text NOT NULL,tokens tsvector NOT NULL,coverage text NOT NULL);
CREATE INDEX text_index_tokens ON mem.text_index USING gin(tokens);
CREATE INDEX material_project ON mem.materials(project_id,state,id);
CREATE TABLE mem.batch_operations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid NOT NULL,idempotency_key text NOT NULL,fingerprint text NOT NULL,manifest jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(actor_id,idempotency_key));
CREATE TABLE mem.command_receipts(actor_id uuid NOT NULL,action text NOT NULL,idempotency_key text NOT NULL,fingerprint text NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(actor_id,action,idempotency_key));
REVOKE ALL ON ALL TABLES IN SCHEMA mem FROM PUBLIC,hub2_mem,hub2_worker;
RESET ROLE;
-- Cross-domain owner capabilities; never exposed to the runtime login.
GRANT SELECT(id,project_id,current_version_id,content_revision,metadata_revision,event_revision,state) ON mem.materials TO hub2_v8_owner;
GRANT SELECT(id,material_id,sha256,size,object_id) ON mem.content_versions TO hub2_v8_owner;

GRANT SELECT(provenance_state) ON mem.materials TO hub2_v8_owner;

GRANT SELECT(provenance_state) ON mem.content_versions TO hub2_v8_owner;
